package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SameTerm;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link FilterInValuesOptimizer}.
 */
public class FilterInValuesOptimizerTest {

	@Test
	public void filterInValuesInvalidatesAncestorMergeJoinPlannedBeforeRewrite() {
		Filter filter = new Filter(pattern("label", "filtered"),
				new SameTerm(Var.of("label"),
						new ValueConstant(SimpleValueFactory.getInstance().createLiteral("kept"))));
		Join plannedMergeJoin = new Join(pattern("label", "outer"), filter);
		plannedMergeJoin.setOrder(Var.of("label"));
		plannedMergeJoin.setMergeJoin(true);
		QueryRoot root = new QueryRoot(plannedMergeJoin);

		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertThat(findAll(root, BindingSetAssignment.class)).singleElement();
		assertThat(plannedMergeJoin.isMergeJoin())
				.as("a post-planning rewrite that adds unordered VALUES must invalidate ancestor merge joins")
				.isFalse();
	}

	@Test
	public void filterInValuesInvalidatesEveryAncestorMergeJoinButKeepsDescendantHints() {
		Join descendantMergeJoin = new Join(pattern("label", "inner1"), pattern("label", "inner2"));
		descendantMergeJoin.setOrder(Var.of("label"));
		descendantMergeJoin.setMergeJoin(true);
		Filter filter = new Filter(descendantMergeJoin,
				new SameTerm(Var.of("label"),
						new ValueConstant(SimpleValueFactory.getInstance().createLiteral("kept"))));
		Join parentMergeJoin = new Join(pattern("label", "outer"), filter);
		parentMergeJoin.setOrder(Var.of("label"));
		parentMergeJoin.setMergeJoin(true);
		Join grandparentMergeJoin = new Join(parentMergeJoin, pattern("label", "outermost"));
		grandparentMergeJoin.setOrder(Var.of("label"));
		grandparentMergeJoin.setMergeJoin(true);
		QueryRoot root = new QueryRoot(grandparentMergeJoin);

		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertThat(findAll(root, BindingSetAssignment.class)).singleElement();
		assertThat(findAll(root, Filter.class)).isEmpty();
		assertThat(parentMergeJoin.isMergeJoin()).as("parent join").isFalse();
		assertThat(grandparentMergeJoin.isMergeJoin()).as("grandparent join").isFalse();

		List<Join> descendantJoins = findAll(root, Join.class).stream()
				.filter(join -> join != parentMergeJoin && join != grandparentMergeJoin
						&& !(join.getLeftArg() instanceof BindingSetAssignment))
				.toList();
		assertThat(descendantJoins).singleElement()
				.as("descendant join hint stays valid because its inputs are unchanged")
				.matches(Join::isMergeJoin);
	}

	private static StatementPattern pattern(String subjectName, String suffix) {
		return new StatementPattern(Var.of(subjectName), Var.of("p" + suffix), Var.of("o" + suffix));
	}

	private static <T extends QueryModelNode> List<T> findAll(TupleExpr tupleExpr, Class<T> type) {
		List<T> nodes = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) throws RuntimeException {
				if (type.isInstance(node)) {
					nodes.add(type.cast(node));
				}
				super.meetNode(node);
			}
		});
		return nodes;
	}
}
